B.c6u=new A.c7("\ud83e\udd16 Oi, eu sou a SIA, sua aliada para vender mais e melhor!",null,B.j6,null,null,null,null,null,null,null)
B.c6b=new A.c7("Prazer em te conhecer!",null,null,null,null,null,null,null,null,null)
B.c6A=new A.c7("Eu sou a SIA, sua assistente inteligente criada para ajudar voc\xea a brilhar nas vendas. Meu objetivo \xe9 facilitar seu trabalho, mostrar como voc\xea pode melhorar e comemorar suas conquistas com voc\xea.",null,null,null,null,null,null,null,null,null)
B.c6E=new A.c7("Aqui est\xe1 como eu posso te ajudar:",null,null,null,null,null,null,null,null,null)
B.f4=new A.aj(null,8,null,null)
B.cdD=new A.NF("\ud83d\udcca An\xe1lise dos Seus Atendimentos","Eu avalio suas intera\xe7\xf5es com os clientes, destacando o que voc\xea faz de melhor e sugerindo como impressionar ainda mais.",null)
B.i7=new A.aj(null,10,null,null)
B.cdG=new A.NF("\ud83d\udcc8 Indicadores Personalizados","Transformo n\xfameros em insights simples para voc\xea entender onde est\xe1 arrasando e onde pode crescer.",null)
B.cdE=new A.NF("\ud83e\udd1d Cultura de Atendimento","Ajudo voc\xea a alinhar seu atendimento aos padr\xf5es que encantam os clientes e criam experi\xeancias inesquec\xedveis.",null)
